	static QueryEvaluationStep tryCreate(Group group, NativeLmdbQuerySource source,
			LmdbNativeEvaluationStrategy strategy, QueryEvaluationContext context, TupleExpr explainTarget,
			Function<StatementPattern, ContextConstraint> contextCompiler) {
		if (group.getGroupElements().isEmpty() || strategy.forcedExecutionStrategyName() != null
				|| !Boolean.parseBoolean(
						System.getProperty("rdf4j.lmdb.directAdjacency.scanAggregates.enabled", "true"))) {
			return null;
		}
		Map<String, ValueExpr> aliases = new HashMap<>();
		List<TupleExpr> wrappers = new ArrayList<>();
		TupleExpr input = group.getArg();
		while (input instanceof Extension || input instanceof Filter) {
			wrappers.add(input);
			if (input instanceof Extension extension) {
				input = extension.getArg();
			} else {
				Filter filter = (Filter) input;
				input = filter.getArg();
			}
		}
		if (!(input instanceof StatementPattern pattern)) {
			return null;
		}
		Var[] vars = { pattern.getSubjectVar(), pattern.getPredicateVar(), pattern.getObjectVar(),
				pattern.getContextVar() };
		Map<String, Integer> fields = new HashMap<>();
		long[] constants = { UNKNOWN, UNKNOWN, UNKNOWN, UNKNOWN };
		for (int field = 0; field < vars.length; field++) {
			Var var = vars[field];
			if (var == null) {
				continue;
			}
			if (!var.isConstant()
					&& (fields.putIfAbsent(var.getName(), field) != null || aliases.containsKey(var.getName()))) {
				return null;
			}
			if (var.hasValue()) {
				// A single ID lookup is a complete point restriction only in a canonical statement domain. A raw
				// source with aliases can otherwise hide other rows for the exact same RDF constant.
				if (!canonicalPatternIds(source)) {
					return null;
				}
				constants[field] = source.idOf(var.getValue(), 1 << field);
				if (constants[field] == UNKNOWN) {
					return null;
				}
			}
		}
		Expressions expressions = new Expressions(fields, aliases);
		BooleanExpression filter = BooleanExpression.constant(true);
		// Resolve bindings in their evaluation scope. Forward references, cycles and unused partial/volatile
		// expressions must decline before execution, even when the aggregate itself would not read them.
		for (int i = wrappers.size() - 1; i >= 0; i--) {
			if (wrappers.get(i) instanceof Extension extension) {
				for (ExtensionElem elem : extension.getElements()) {
					ValueExpr alias = elem.getExpr();
					if (fields.containsKey(elem.getName()) || aliases.containsKey(elem.getName())
							|| expressions.field(alias) < 0 && expressions.integer(alias) == null
									&& expressions.bool(alias) == null && !(alias instanceof ValueConstant)) {
						return null;
					}
					aliases.put(elem.getName(), alias);
				}
			} else if (wrappers.get(i) instanceof Filter selection) {
				if (!FilterBindingScope.allowsAllConditionBindings(selection)) {
					return null;
				}
				BooleanExpression compiled = expressions.bool(selection.getCondition());
				if (compiled == null) {
					return null;
				}
				filter = filter.and(compiled);
			}
		}
		String[] names = group.getGroupBindingNames().toArray(String[]::new);
		int[] groups = new int[names.length];
		for (int i = 0; i < groups.length; i++) {
			groups[i] = expressions.field(new Var(names[i]));
			if (groups[i] < 0) {
				return null;
			}
		}
		Channel[] channels = new Channel[group.getGroupElements().size()];
		for (int i = 0; i < channels.length; i++) {
			GroupElem element = group.getGroupElements().get(i);
			if (element.getOperator() instanceof Count count) {
				int field = count.getArg() == null ? -1 : expressions.field(count.getArg());
				ValueExpr argument = expressions.resolve(count.getArg(), 0);
				IntegerExpression number = field < 0 && argument != null ? expressions.integer(argument) : null;
				if (count.isDistinct() && argument == null || argument != null && field < 0
						&& !(argument instanceof ValueConstant) && number == null) {
					return null;
				}
				channels[i] = new Channel(element.getName(), field, count.isDistinct(), false, number,
						argument instanceof ValueConstant constant ? constant.getValue() : null);
			} else if (element.getOperator() instanceof Sum sum) {
				IntegerExpression number = expressions.integer(sum.getArg());
				if (number == null) {
					return null;
				}
				channels[i] = new Channel(element.getName(), -1, sum.isDistinct(), true, number, null);
			} else {
				return null;
			}
		}
		// Closed kind predicates need the census coefficients even when every consumer is COUNT. Other COUNT-only
		// demands retain the existing root/domain alternatives; admission never makes this algorithm mandatory.
		boolean needsCensus = Arrays.stream(channels).anyMatch(channel -> channel.sum || channel.field == C)
				|| Arrays.stream(groups).anyMatch(field -> field == C) || filter.mask != 0
				|| Arrays.stream(channels)
						.anyMatch(channel -> channel.expression != null && channel.expression.mask != 0);
		if (!needsCensus) {
			return null;
		}
		return new LmdbNativeCensusAggregate(source, strategy, context, group, explainTarget, pattern,
				contextCompiler.apply(pattern), constants, names, groups, channels, filter);
	}

